css:
/* ==== INTERFACE ====
方向：无图时尚编辑语言；高对比细衬线标题、清晰无衬线正文、精细规则线与克制的朱红色点，适合投影中的中英混排与指数增长数字展示。
token --bg：页面底色。
token --text：正文与主要墨色。
token --muted：辅助文字。
token --focus：键盘焦点色。
token --accent：增长率与当前强调色。
token --font-sans：正文与控件的中英混排字体。
token --font-title：标题的中英混排字体。
token --font-number：数字字体。
token --fs-h1/--fs-h2/--fs-lead/--fs-body/--fs-sec/--fs-label/--fs-tick：投影字阶。
class .nt-title：中英混排页标题；拉丁优先 Bodoni Moda，汉字承接站酷小薇体。
class .nt-body：中英混排正文；拉丁优先 Inter，汉字承接 Noto Sans SC。
class .nt-number：金额、百分比、年份与刻度数字；使用 Inter 等宽数字特性。
class .nt-kicker：短栏目名或章节眉题。
class .nt-rule：编辑式细分隔线。
class .nt-emphasis：正文中的增长率或关键结论强调。
class .nt-controls：课堂交互控件的高对比编辑式外观。
variant opening：开篇使用更强的黑白反差、放大的标题字阶与偏右的编辑式光带；适合短标题首屏。
默认：不设 data-variant；纯 CSS 纸面光感与斜切留白，无图片亦可完整使用。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-zcool-xiaowei";
  src: url("fonts/library/zcool-xiaowei/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-bodoni-moda";
  src: url("fonts/library/bodoni-moda/face-0.ttf");
  font-weight: 400 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-bodoni-moda";
  src: url("fonts/library/bodoni-moda/face-1.ttf");
  font-weight: 400 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

:root {
  --bg: #f4f1ed;
  --text: #111111;
  --muted: #625f5b;
  --focus: #175fc4;
  --accent: #c93125;
  --rule: rgba(17, 17, 17, 0.28);
  --paper-light: rgba(255, 255, 255, 0.72);
  --paper-shade: rgba(17, 17, 17, 0.045);

  --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
  --font-title: "NTF-bodoni-moda", "NTF-zcool-xiaowei", serif;
  --font-number: "NTF-inter", sans-serif;

  --fs-h1: clamp(76px, 7vw, 116px);
  --fs-h2: clamp(48px, 4.2vw, 70px);
  --fs-lead: clamp(27px, 2vw, 34px);
  --fs-body: clamp(20px, 1.45vw, 25px);
  --fs-sec: clamp(17px, 1.2vw, 20px);
  --fs-label: 16px;
  --fs-tick: 14px;

  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 36px;
  --space-5: 56px;
  --space-6: 80px;
}

html[data-variant="opening"] {
  --bg: #ece9e5;
  --text: #090909;
  --muted: #57534f;
  --accent: #bd2d22;
  --rule: rgba(9, 9, 9, 0.34);
  --paper-light: rgba(255, 255, 255, 0.82);
  --paper-shade: rgba(0, 0, 0, 0.065);
  --fs-h1: clamp(92px, 8.6vw, 142px);
}

#stage {
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(104deg, transparent 0 66%, var(--paper-light) 66.1% 86%, transparent 86.1%),
    radial-gradient(ellipse at 18% 10%, rgba(255, 255, 255, 0.72) 0, transparent 46%),
    linear-gradient(90deg, transparent 0 5.4%, var(--rule) 5.4% calc(5.4% + 1px), transparent calc(5.4% + 1px)),
    linear-gradient(180deg, var(--paper-shade), transparent 22%, transparent 78%, rgba(255, 255, 255, 0.24));
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

html[data-variant="opening"] #stage {
  background-image:
    linear-gradient(105deg, transparent 0 58%, rgba(255, 255, 255, 0.86) 58.1% 80%, transparent 80.1%),
    linear-gradient(90deg, rgba(0, 0, 0, 0.055) 0 34%, transparent 34.1%),
    radial-gradient(ellipse at 72% 18%, rgba(255, 255, 255, 0.76), transparent 45%),
    linear-gradient(90deg, transparent 0 5.4%, var(--rule) 5.4% calc(5.4% + 1px), transparent calc(5.4% + 1px));
}

.nt-title {
  margin: 0;
  color: var(--text);
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 500;
  font-style: normal;
  line-height: 0.92;
  letter-spacing: -0.035em;
  text-wrap: balance;
  font-synthesis: none;
}

.nt-title[lang="zh"],
.nt-title :lang(zh) {
  font-family: "NTF-zcool-xiaowei", serif;
  font-weight: 400;
  letter-spacing: 0;
  line-height: 1.04;
}

.nt-title[lang="en"],
.nt-title :lang(en) {
  font-family: "NTF-bodoni-moda", serif;
  font-weight: 500;
}

.nt-title small,
.nt-title.nt-title-secondary {
  font-size: var(--fs-h2);
  line-height: 1.02;
}

.nt-body {
  margin: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 400;
  line-height: 1.56;
  letter-spacing: 0;
  text-wrap: pretty;
  font-synthesis: none;
}

.nt-body[lang="en"],
.nt-body :lang(en) {
  font-family: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
}

.nt-body[lang="zh"],
.nt-body :lang(zh) {
  font-family: "NTF-noto-sans-sc", sans-serif;
}

.nt-body strong {
  font-weight: 700;
}

.nt-body a {
  color: currentColor;
  text-decoration-color: var(--accent);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.18em;
}

.nt-number {
  color: var(--text);
  font-family: var(--font-number);
  font-weight: 650;
  font-variant-numeric: tabular-nums lining-nums;
  font-feature-settings: "tnum" 1, "lnum" 1, "zero" 1;
  letter-spacing: -0.025em;
  line-height: 1;
  white-space: nowrap;
  font-synthesis: none;
}

.nt-number[aria-label] {
  speak-as: numbers;
}

.nt-kicker {
  margin: 0;
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 650;
  line-height: 1.35;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nt-kicker :lang(zh),
.nt-kicker[lang="zh"] {
  letter-spacing: 0.08em;
  text-transform: none;
}

.nt-lead {
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-lead);
  font-weight: 450;
  line-height: 1.42;
  text-wrap: balance;
}

.nt-caption {
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 450;
  line-height: 1.45;
}

.nt-tick {
  color: var(--muted);
  font-family: var(--font-number);
  font-size: var(--fs-tick);
  font-variant-numeric: tabular-nums lining-nums;
  line-height: 1.35;
}

.nt-rule {
  border: 0;
  border-top: 1px solid var(--rule);
  margin-block: var(--space-3);
}

.nt-emphasis {
  color: var(--accent);
  font-weight: 700;
}

.nt-number.nt-emphasis {
  color: var(--accent);
  font-weight: 760;
}

.nt-controls {
  --surface: rgba(244, 241, 237, 0.94);
  color: var(--text);
  background: var(--surface);
  border: 1px solid rgba(17, 17, 17, 0.48);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(17, 17, 17, 0.1);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.35;
}

.nt-controls button,
.nt-controls input,
.nt-controls select,
.nt-controls output {
  color: var(--text);
  font: inherit;
}

.nt-controls button {
  min-height: 44px;
  padding: 9px 18px;
  background: transparent;
  border: 1px solid currentColor;
  border-radius: 0;
  font-weight: 650;
}

.nt-controls button[aria-pressed="true"],
.nt-controls button[aria-selected="true"] {
  color: var(--bg);
  background: var(--text);
}

.nt-controls input[type="range"] {
  accent-color: var(--accent);
}

.nt-controls :focus-visible,
.nt-body a:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 4px;
}

.nt-controls button:disabled,
.nt-controls input:disabled,
.nt-controls select:disabled {
  opacity: 0.48;
}

::selection {
  color: #ffffff;
  background: var(--accent);
}

@media (prefers-contrast: more) {
  :root,
  html[data-variant="opening"] {
    --muted: #3d3b38;
    --rule: rgba(0, 0, 0, 0.58);
  }

  .nt-controls {
    border-width: 2px;
    box-shadow: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .nt-controls *,
  .nt-controls *::before,
  .nt-controls *::after {
    scroll-behavior: auto;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
